// The reTerminal E-series' own layout (E1001, E1002, E1003, E1004): a status
// bar along the edge the keys are on, with the signal, the battery and the time
// the picture was drawn, and under each key what holding it does. It draws
// when the scene draws and never on its own, so an e-paper panel refreshes no
// more often for it. A double press of the green key opens the scene list,
// where the bar says what each key does there. On the E1003, whose glass is
// touch, the bar's parts are buttons too.
const INK = '#000000'
const PAPER = '#ffffff'
// Spectra 6 inks as the panel shows them (dither.nim's measured table), so a
// colour panel draws them solid.
const GREEN = '#2a5531'
const RED = '#6b1119'

const pad = (n) => String(n).padStart(2, '0')

// Where the keys are on each model, the panel unturned: along an edge, each
// as a share of its length from the start (Seeed's drawings). The E1001,
// E1002 and E1003 have them on top, right of centre; seen from the front the
// one labelled RIGHT is the left one and LEFT the middle one (their arrows are
// printed on the back), the green REFRESH key last. The E1004 hangs upright as
// a picture with touch keys under it, REFRESH, LEFT and RIGHT from the left.
const TOP_KEYS = [
  { label: 'RIGHT', at: 0.56 },
  { label: 'LEFT', at: 0.615 },
  { label: 'REFRESH', at: 0.685 },
]
const MODELS = {
  e1001: { name: 'E1001', edge: 'top', keys: TOP_KEYS, touch: false },
  e1002: { name: 'E1002', edge: 'top', keys: TOP_KEYS, touch: false },
  e1003: { name: 'E1003', edge: 'top', keys: TOP_KEYS, touch: true },
  e1004: {
    name: 'E1004',
    edge: 'below',
    keys: [
      { label: 'REFRESH', at: 0.41 },
      { label: 'LEFT', at: 0.5 },
      { label: 'RIGHT', at: 0.59 },
    ],
    touch: false,
  },
}
// What the planes give each model when a frame has no map to tell (the
// preview): the arrows held walk the scenes, and the green key held talks on
// the three with a microphone (fos_board.c, embedded_firmware.py).
const ARROWS = [
  { event: 'button', match: { label: 'LEFT', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'prev' } },
  { event: 'button', match: { label: 'RIGHT', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'next' } },
]
const TALK = { event: 'button', match: { label: 'REFRESH', action: 'longPress' }, emit: 'voiceChat', as: {} }
const SWIPES = [
  { event: 'edgeSwipe', match: { edge: 'left' }, emit: 'back', as: {} },
  { event: 'edgeSwipe', match: { edge: 'right' }, emit: 'forward', as: {} },
  { event: 'edgeSwipe', match: { edge: 'bottom' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'top' }, emit: 'sceneSettings', as: {} },
]
const DEFAULT_MAPS = {
  e1001: [...ARROWS, TALK],
  e1002: [...ARROWS, TALK],
  e1003: [...ARROWS, TALK, ...SWIPES],
  e1004: ARROWS,
}
// The key the layout listens to: pressed twice, the scene list.
const LIST_KEY = 'REFRESH'

const ICON = {
  next: 'M8.59,16.58L13.17,12L8.59,7.41L10,6L16,12L10,18L8.59,16.58Z',
  prev: 'M15.41,16.58L10.83,12L15.41,7.41L14,6L8,12L14,18L15.41,16.58Z',
  mic: 'M12,2A3,3 0 0,1 15,5V11A3,3 0 0,1 12,14A3,3 0 0,1 9,11V5A3,3 0 0,1 12,2M19,11C19,14.53 16.39,17.44 13,17.93V21H11V17.93C7.61,17.44 5,14.53 5,11H7A5,5 0 0,0 12,16A5,5 0 0,0 17,11H19Z',
  refresh: 'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  apps: 'M4,4H10V10H4V4M14,4H20V10H14V4M4,14H10V20H4V14M14,14H20V20H14V14Z',
  cog: 'M12,15.5A3.5,3.5 0 0,1 8.5,12A3.5,3.5 0 0,1 12,8.5A3.5,3.5 0 0,1 15.5,12A3.5,3.5 0 0,1 12,15.5M19.43,12.97C19.47,12.65 19.5,12.33 19.5,12C19.5,11.67 19.47,11.34 19.43,11L21.54,9.37C21.73,9.22 21.78,8.95 21.66,8.73L19.66,5.27C19.54,5.05 19.27,4.96 19.05,5.05L16.56,6.05C16.04,5.66 15.5,5.32 14.87,5.07L14.5,2.42C14.46,2.18 14.25,2 14,2H10C9.75,2 9.54,2.18 9.5,2.42L9.13,5.07C8.5,5.32 7.96,5.66 7.44,6.05L4.95,5.05C4.73,4.96 4.46,5.05 4.34,5.27L2.34,8.73C2.21,8.95 2.27,9.22 2.46,9.37L4.57,11C4.53,11.34 4.5,11.67 4.5,12C4.5,12.33 4.53,12.65 4.57,12.97L2.46,14.63C2.27,14.78 2.21,15.05 2.34,15.27L4.34,18.73C4.46,18.95 4.73,19.03 4.95,18.95L7.44,17.94C7.96,18.34 8.5,18.68 9.13,18.93L9.5,21.58C9.54,21.82 9.75,22 10,22H14C14.25,22 14.46,21.82 14.5,21.58L14.87,18.93C15.5,18.67 16.04,18.34 16.56,17.94L19.05,18.95C19.27,19.03 19.54,18.95 19.66,18.73L21.66,15.27C21.78,15.05 21.73,14.78 21.54,14.63L19.43,12.97Z',
  open: 'M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M10,17V7L16,12L10,17Z',
}

const Icon = ({ d, size }) => (
  <svg viewBox="0 0 24 24" width={size} height={size}>
    <path d={d} fill="currentColor" />
  </svg>
)

// The model: the owner's choice, else the panel's size and colours.
function modelOf(frame, setting) {
  if (MODELS[setting]) return setting
  const scale = Number(frame.scale) || 1
  const long = Math.round(Math.max(frame.width, frame.height) * scale)
  if (long >= 1800) return 'e1003'
  if (long >= 1500) return 'e1004'
  return frame.color === false ? 'e1001' : 'e1002'
}

// The side of the picture the keys are on, and the share along it their order
// runs from. The E1001-E1003 keys are on the panel's top edge, which the
// frame's rotation turns (90: the left side, upside down: the bottom); the
// E1004's are under its picture whichever way it hangs. The owner's "Keys"
// setting wins.
function keySide(model, frame, setting) {
  if (['top', 'bottom', 'left', 'right'].includes(setting)) return setting
  if (MODELS[model].edge === 'below') return 'bottom'
  const rotate = ((Number(frame.rotate) || 0) % 360 + 360) % 360
  return { 0: 'top', 90: 'left', 180: 'bottom', 270: 'right' }[rotate] || 'top'
}
// The E1004's order is as seen, left to right, under the picture; the others'
// is the top edge's, which reads backwards once turned to the left or the bottom.
const along = (model, side, at) =>
  MODELS[model].edge === 'below' || side === 'top' || side === 'right' ? at : 1 - at

function said(rule) {
  const as = rule.as || {}
  switch (rule.emit) {
    case 'setCurrentScene':
      return as.direction === 'prev' ? 'Prev' : as.direction === 'next' ? 'Next' : 'Scene'
    case 'voiceChat': return 'Talk'
    case 'sceneSwitcher': return 'Scenes'
    case 'sceneSettings': return 'Settings'
    case 'toggleScreen': return 'Screen'
    case 'render': return 'Refresh'
    case 'back': return 'Back'
    case 'forward': return 'Forward'
    default: return rule.emit ? String(rule.emit) : null
  }
}
function iconOf(rule, label) {
  if (rule && rule.emit === 'voiceChat') return ICON.mic
  if (rule && rule.emit === 'setCurrentScene') return (rule.as || {}).direction === 'prev' ? ICON.prev : ICON.next
  if (rule && (rule.emit === 'sceneSwitcher')) return ICON.apps
  if (rule && (rule.emit === 'sceneSettings')) return ICON.cog
  return label === 'LEFT' ? ICON.prev : label === 'RIGHT' ? ICON.next : ICON.refresh
}
function keyRule(map, label, action) {
  return map.find((rule) => rule.event === 'button' && rule.match && rule.match.label === label &&
    (rule.match.action || 'press') === action)
}
const swipeRule = (map, edge) => map.find((rule) => rule.event === 'edgeSwipe' && rule.match && rule.match.edge === edge)
const mapOf = (frame, model) => (Array.isArray(frame.eventMap) ? frame.eventMap : DEFAULT_MAPS[model])
const listShows = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSwitcher')
// The layout's own double press opens the list where the frame's map leaves it free.
const listKeyFree = (map) => !keyRule(map, LIST_KEY, 'doublePress')

export function onEvent(app, context) {
  const press = context.payload || {}
  if (context.event === 'button' && press.label === LIST_KEY && press.action === 'doublePress' && !app.frame.systemScene &&
      listKeyFree(mapOf(app.frame, modelOf(app.frame, app.state.model)))) {
    frameos.dispatch('sceneSwitcher')
  }
  return false
}

function Signal({ rssi, u }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${Math.max(1, Math.round(u * 0.4))}px] h-[${Math.round(u * 3)}px]`}>
      {[0.3, 0.55, 0.8, 1].map((share, i) => (
        <div className={`w-[${Math.max(2, Math.round(u * 0.6))}px] h-[${Math.round(u * 3 * share)}px] ${i < level ? `bg-[${INK}]` : `border border-[${INK}]`}`} />
      ))}
    </div>
  )
}

function Battery({ percent, u, color }) {
  if (typeof percent !== 'number') return null
  const low = percent <= 15
  const ink = low && color ? RED : INK
  const w = Math.round(u * 5)
  const h = Math.round(u * 2.6)
  const line = Math.max(1, Math.round(u * 0.3))
  const inner = Math.max(0, Math.round((w - 4 * line) * Math.min(100, Math.max(0, percent)) / 100))
  return (
    <div className={`flex items-center gap-[${line}px] text-[${ink}]`}>
      <div className={`flex items-center w-[${w}px] h-[${h}px] p-[${line}px] border-[${line}px] border-[${ink}] rounded-[${line * 2}px]`}>
        <div className={`h-full w-[${inner}px] bg-[${ink}]`} />
      </div>
      <div className={`w-[${line * 2}px] h-[${Math.round(h / 2.5)}px] bg-[${ink}]`} />
      <span className={`pl-[${line * 2}px] font-semibold`}>{`${percent}%`}</span>
    </div>
  )
}

// One key's cap, hanging from the edge beside the key: what the key does,
// in an icon and a word. The green key is green where the panel has the ink.
function Cap({ side, size, icon, word, green, lit }) {
  const across = side === 'left' || side === 'right'
  const corner = { top: 'rounded-b-[10px]', bottom: 'rounded-t-[10px]', left: 'rounded-r-[10px]', right: 'rounded-l-[10px]' }[side]
  const look = lit ? `bg-[${INK}] text-[${PAPER}]` : green ? `bg-[${GREEN}] text-[${PAPER}]` : `bg-[${PAPER}] text-[${INK}] border-2 border-[${INK}]`
  return (
    <div className={`flex flex-col items-center justify-center gap-[${Math.round(size * 0.04)}px] w-full h-full ${corner} ${look}`}>
      <Icon d={icon} size={Math.round(size * 0.44)} />
      <span className={`text-[${Math.round(size * 0.2)}px] font-bold leading-none whitespace-nowrap`}>{word}</span>
    </div>
  )
}

function caps(model, side, length, size, list) {
  const across = side === 'left' || side === 'right'
  // As wide as the bar is deep, and no wider than the keys are apart: the
  // E1001's are 44 px apart on an 800 px panel.
  const places = list.map((cap) => along(model, side, cap.at) * length).sort((a, b) => a - b)
  let apart = Infinity
  for (let i = 1; i < places.length; i++) apart = Math.min(apart, places[i] - places[i - 1])
  const span = Math.round(Math.min(size, apart - 2))
  return list.map((cap) => {
    const centre = Math.round(along(model, side, cap.at) * length)
    const start = Math.max(0, Math.min(length - span, centre - Math.round(span / 2)))
    const place = across ? `top-[${start}px] left-0 w-full h-[${span}px]` : `left-[${start}px] top-0 h-full w-[${span}px]`
    return (
      <div className={`absolute ${place} px-[2px]`}>
        <Cap side={side} size={size} icon={cap.icon} word={cap.word} green={cap.green} lit={cap.lit} />
      </div>
    )
  })
}

// Each key's cap: on a scene what holding it does; over the scene list what a
// press does there (the list's keys: LEFT and RIGHT walk it, REFRESH opens).
function capsFor(model, map, onList, colour) {
  return MODELS[model].keys.map((key) => {
    const green = key.label === 'REFRESH' && colour
    if (onList) {
      if (key.label === 'REFRESH') return { at: key.at, icon: ICON.open, word: 'Open', green, lit: !green }
      return { at: key.at, icon: key.label === 'LEFT' ? ICON.prev : ICON.next, word: key.label === 'LEFT' ? 'Prev' : 'Next', green }
    }
    const held = keyRule(map, key.label, 'longPress')
    // A green key with no hold of its own: the layout's double press.
    if (!held && key.label === LIST_KEY && listKeyFree(map)) return { at: key.at, icon: ICON.apps, word: '2×', green }
    return { at: key.at, icon: iconOf(held, key.label), word: held ? said(held) : '–', green }
  })
}

// Over the scene list, how to move through it.
const hints = (model) => (MODELS[model].touch ? 'Tap one, or the arrows and the green key' : 'Arrows move, the green key opens')

function Bar({ app, model, side, W, H, u, onList }) {
  const frame = app.frame
  const touch = MODELS[model].touch
  const colour = frame.color !== false
  const map = mapOf(frame, model)
  const across = side === 'left' || side === 'right'
  const size = Math.round(u * (across ? 11.5 : 11.5))
  const now = new Date()
  const showKeys = app.state.bar !== 'quiet'
  const text = Math.round(u * 3.6)
  const title = app.state.title || frame.sceneName || ''
  // Under the name, how to reach the scene list where the keys cannot say it.
  const tip = onList ? hints(model) : touch ? (swipeRule(map, 'bottom') ? 'Swipe up or tap for all scenes' : 'Tap for all scenes')
    : listKeyFree(map) ? 'Green key 2×: all scenes' : null
  const status = (
    <div
      className={`flex ${across ? 'flex-col' : 'flex-row'} items-center gap-[${Math.round(u * 2)}px] shrink-0`}
      onClick={touch ? () => frameos.dispatch('sceneSettings', { page: 'frame' }) : undefined}
    >
      <Signal rssi={frame.wifiRssi} u={u} />
      <Battery percent={frame.batteryPercent} u={u} color={colour} />
      <span className="whitespace-nowrap font-semibold">{`${pad(now.getHours())}:${pad(now.getMinutes())}`}</span>
    </div>
  )
  const name = (
    <div
      className={`flex items-center gap-[${Math.round(u)}px] min-w-0 ${across ? '' : 'flex-1'}`}
      onClick={touch ? () => frameos.dispatch('sceneSwitcher') : undefined}
    >
      {touch ? <Icon d={ICON.apps} size={Math.round(u * 3.6)} /> : null}
      <div className="flex flex-col min-w-0">
        <span className="truncate font-bold">{onList ? 'Scenes' : title}</span>
        {tip ? <span className={`truncate text-[${Math.round(text * 0.72)}px]`}>{tip}</span> : null}
      </div>
    </div>
  )
  const keyZone = MODELS[model].keys.map((key) => along(model, side, key.at))
  const zoneStart = Math.min(...keyZone)
  const zoneEnd = Math.max(...keyZone)
  // Room left and right of the keys' caps, for the name and the status.
  const length = across ? H : W
  const before = Math.max(0, Math.round(zoneStart * length - size * 0.6 - u * 2))
  const after = Math.max(0, Math.round(length - zoneEnd * length - size * 0.6 - u * 2))
  const gear = touch ? (
    <div className={`flex items-center justify-center w-[${Math.round(u * 6)}px] h-[${Math.round(u * 6)}px] rounded-full border-2 border-[${INK}] shrink-0`}
      onClick={() => frameos.dispatch('sceneSettings')}>
      <Icon d={ICON.cog} size={Math.round(u * 4)} />
    </div>
  ) : null
  const edgeLine = { top: 'border-b-2', bottom: 'border-t-2', left: 'border-r-2', right: 'border-l-2' }[side]
  if (across) {
    return (
      <div className={`relative flex flex-col items-center justify-end gap-[${Math.round(u * 2)}px] w-[${size}px] h-full pb-[${Math.round(u * 2)}px] shrink-0 bg-[${PAPER}] text-[${INK}] text-[${Math.round(text * 0.8)}px] ${edgeLine} border-[${INK}]`}>
        {showKeys ? caps(model, side, H, size, capsFor(model, map, onList, colour)) : null}
        {onList ? null : gear}
        {status}
      </div>
    )
  }
  return (
    <div className={`relative flex items-center h-[${size}px] w-full shrink-0 bg-[${PAPER}] text-[${INK}] text-[${text}px] ${edgeLine} border-[${INK}]`}>
      {showKeys ? caps(model, side, W, size, capsFor(model, map, onList, colour)) : null}
      <div className={`flex items-center gap-[${Math.round(u * 2)}px] h-full pl-[${Math.round(u * 3)}px] ${showKeys ? `w-[${before}px]` : 'flex-1'} min-w-0`}>
        {name}
          {onList ? null : gear}
      </div>
      {showKeys ? <div className="flex-1" /> : null}
      <div className={`flex items-center justify-end h-full pr-[${Math.round(u * 3)}px] ${showKeys ? `w-[${after}px]` : ''} min-w-0`}>
        {status}
      </div>
    </div>
  )
}

export function get(app) {
  const frame = app.frame
  const W = frame.width
  const H = frame.height
  const u = Math.min(W, H) / 100
  const model = modelOf(frame, app.state.model)
  const side = keySide(model, frame, app.state.keys)
  const onList = listShows(frame)
  // The settings get the whole panel: they have a keyboard to show.
  if (frame.systemScene && !onList) return <yield />
  if (app.state.bar === 'off' && !onList) return <yield />
  const across = side === 'left' || side === 'right'
  const bar = <Bar app={app} model={model} side={side} W={W} H={H} u={u} onList={onList} />
  const first = side === 'top' || side === 'left'
  const body = (
    <div className="flex flex-col flex-1 min-w-0 min-h-0">
      <yield />
    </div>
  )
  return (
    <div className={`flex ${across ? 'flex-row' : 'flex-col'} w-full h-full bg-[${PAPER}]`}>
      {first ? bar : null}
      {body}
      {first ? null : bar}
    </div>
  )
}
